const patternText = (text, language) => {
  const normalized = String(text ?? '').trim();
  const lang = normalizeLanguage(language);
  for (const item of PATTERN_TRANSLATIONS) {
    const match = normalized.match(item.re);
    if (!match) continue;
    const values = item.values || item.make(match);
    return values[lang] || values.uz || normalized;
  }
  return null;
};

export const sourceText = (value, language = 'uz', params = {}) => {
  if (value == null) return '';
  const text = String(value);
  if (!text.trim() || ACCEPTED.test(text.trim())) return interpolate(text, params);
  const trimmed = text.trim();
  const lang = normalizeLanguage(language);
  const row = byKey.get(trimmed);
  if (row) {
    const rowVal = row[lang] || row.uz || text;
    if (lang === 'tg' && !row.tg && typeof medinson1038Translate === 'function') {
      const fromRuntime = medinson1038Translate(rowVal, lang);
      if (fromRuntime && fromRuntime !== rowVal) return interpolate(fromRuntime, params);
      const fromRuntimeDirect = medinson1038Translate(trimmed, lang);
      if (fromRuntimeDirect && fromRuntimeDirect !== trimmed) return interpolate(fromRuntimeDirect, params);
    }
    return interpolate(rowVal, params);
  }
  const patterned = patternText(trimmed, language);
  if (patterned) return interpolate(patterned, params);
  const terminalPunctuation = trimmed.match(/^(.+?)([.!?])$/);
  if (terminalPunctuation) {
    const punctRow = byKey.get(terminalPunctuation[1]);
    if (punctRow) {
      const rowVal = punctRow[lang] || punctRow.uz || terminalPunctuation[1];
      if (lang === 'tg' && !punctRow.tg && typeof medinson1038Translate === 'function') {
        const fromRuntime = medinson1038Translate(rowVal, lang);
        if (fromRuntime && fromRuntime !== rowVal) return interpolate(fromRuntime + terminalPunctuation[2], params);
        const fromRuntimeDirect = medinson1038Translate(terminalPunctuation[1], lang);
        if (fromRuntimeDirect && fromRuntimeDirect !== terminalPunctuation[1]) return interpolate(fromRuntimeDirect + terminalPunctuation[2], params);
      }
      return interpolate(rowVal + terminalPunctuation[2], params);
    }
  }
  if (lang === 'tg' && typeof medinson1038Translate === 'function') {
    const fromRuntimeDirect = medinson1038Translate(trimmed, lang);
    if (fromRuntimeDirect && fromRuntimeDirect !== trimmed) return interpolate(fromRuntimeDirect, params);
  }
  return interpolate(text, params);
};

export const translateSourceText = sourceText;
export default sourceText;
